    function foodSearchTerms(food){const terms=[food.name,food.category,...(foodSearchSynonyms[food.name]||[])];if(food.category==='肉类'){terms.push('肉');if(food.name.startsWith('鸡'))terms.push('鸡肉','鸡','禽肉');if(food.name.startsWith('猪'))terms.push('猪肉','猪');if(food.name.startsWith('牛'))terms.push('牛肉','牛');if(food.name.startsWith('羊'))terms.push('羊肉','羊');if(food.name.startsWith('鸭'))terms.push('鸭肉','鸭');if(food.name.startsWith('火鸡'))terms.push('火鸡肉','禽肉')}if(food.category==='鱼类')terms.push('鱼','鱼肉','水产');if(food.category==='蔬菜')terms.push('菜');if(food.category==='水果')terms.push('果');return terms}
