    function getShelfGuide(name){if(shelfLifeDatabase[name])return shelfLifeDatabase[name];const food=getFood(name);if(food.category==='肉类')return {days:1,range:'冷藏约 1–2 天（生鲜参考）',note:'按生鲜肉及时冷藏估算，商品包装标示优先。'};if(food.category==='鱼类')return {days:1,range:'冷藏约 1–2 天（生鲜参考）',note:'按生鲜鱼类及时冷藏估算，商品包装标示优先。'};if(food.category==='水果')return {days:5,range:'冷藏约 5 天（参考值）',note:'成熟度和包装状态会影响期限，商品包装标示优先。'};if(food.category==='蔬菜')return {days:3,range:'冷藏约 3 天（参考值）',note:'是否切开、包装和新鲜度会影响期限，商品包装标示优先。'};return {days:3,range:'冷藏约 3 天（参考值）',note:'实际期限因包装和开封状态而异，商品包装标示优先。'}}
