    const recipeMethods={
      'chicken-broccoli':['鸡胸肉擦干后切成约 1 厘米厚片，加入生抽 5 克、盐 1 克和黑胡椒 0.5 克，抓匀腌 10 分钟。','西兰花掰成小朵，沸水中焯 1–2 分钟，捞出沥干。','平底锅加食用油 5 克，中火将鸡胸肉每面煎约 3 分钟，中心熟透后盛出。','用锅中余油翻炒西兰花约 2 分钟，补剩余盐，和鸡胸肉一起装盘。'],
      'tomato-egg':['番茄切块，鸡蛋打散；准备食用油 8 克、盐 2 克和白糖 3 克。','锅烧热后倒入约一半食用油，炒熟鸡蛋至蓬松，盛出备用。','加入剩余食用油和番茄，中火翻炒 3–4 分钟至出汁，可加少量清水。','倒回鸡蛋，加盐和白糖翻炒约 1 分钟，尝味后出锅。'],
      'tofu-soup':['番茄切块，豆腐切约 2 厘米小块，菠菜洗净切段。','锅中加食用油 3 克炒软番茄约 3 分钟，加入约 600 毫升清水煮开。','放入豆腐小火煮 5 分钟，再放菠菜煮 1 分钟。','加盐 2 克、白胡椒 0.5 克；关火后淋香油 2 克。'],
      'corn-soup':['鸡胸肉切块，玉米切段，胡萝卜切滚刀块；鸡肉冷水下锅焯至变色后捞出。','锅中放鸡肉、玉米、胡萝卜、姜 5 克和约 1 升清水，加入料酒 5 克。','水开后撇去浮沫，转小火加盖炖 30–35 分钟。','出锅前加盐 2 克调味；若用带骨鸡肉，炖煮时间延长至约 45 分钟。'],
      'mushroom-spinach':['蘑菇切片，菠菜洗净切段，鸡蛋加少量清水打散。','锅中加入食用油 5 克，蛋液炒至刚凝固后盛出。','用锅中余油炒蘑菇 3 分钟至出水变软，加入菠菜翻炒约 1 分钟。','倒回鸡蛋，加生抽 5 克和盐 2 克翻匀，菠菜变软即可关火。'],
      'beef-tomato-stew':['牛腩切块冷水下锅，煮沸 2 分钟后捞出冲净；番茄切块，土豆切滚刀块。','锅中加食用油 8 克，放姜 8 克和牛腩翻炒 2 分钟，加入生抽 10 克。','加约 800 毫升热水，小火加盖炖 45 分钟；再放番茄和土豆继续炖 20–25 分钟。','牛腩软烂、土豆熟透后加入盐 3 克和白糖 3 克调味。'],
      'beef-enoki-hotpot':['娃娃菜切块，金针菇去根洗净；肥牛卷提前解冻并分散。','锅中加入约 700 毫升清水或无盐高汤，烧开后下娃娃菜煮 3 分钟。','放入金针菇煮 2 分钟，再分批下肥牛卷，煮至变色熟透约 1–2 分钟。','蘸料用生抽 10 克、米醋 5 克、香油 3 克和盐 2 克调匀；想清淡可不蘸完。'],
      'tomato-beef-hotpot':['番茄切块，金针菇去根，娃娃菜切段；准备食用油 5 克和盐 2 克。','锅中加食用油炒软番茄约 3 分钟，加入约 600 毫升清水，煮沸后用勺压出番茄汁。','先放娃娃菜煮 3 分钟，再放金针菇煮 2 分钟；肥牛卷分批下锅。','肥牛卷煮至完全熟透后加盐调味。番茄本身偏酸时可少量加糖，但额外糖未计入热量。'],
      'mushroom-chicken-hotpot':['鸡腿肉切薄片，香菇切片，金针菇去根，娃娃菜切段；姜切片。','锅中加约 800 毫升清水、姜 6 克和料酒 8 克煮开。','放入香菇和娃娃菜煮 5 分钟，加入鸡腿肉片，分散煮至完全熟透。','最后放金针菇煮 2–3 分钟，加盐 2 克调味。'],
      'sauerkraut-pork-hotpot':['酸菜冲洗后挤干切丝；豆腐切块，五花肉片解冻分开。','锅中加入约 700 毫升清水、姜 6 克和料酒 8 克，放入酸菜小火煮 10 分钟。','放入五花肉片煮至完全熟透，再加入豆腐和白菜煮 5 分钟。','酸菜自带咸味，先尝汤再决定是否加入盐 1 克。'],
      'spicy-tripe-hotpot':['毛肚洗净切片，娃娃菜切段，嫩豆腐切块；准备火锅底料 20 克。','锅中加入约 700 毫升清水和火锅底料，煮沸并搅匀。','先下娃娃菜和豆腐煮熟，再放肥牛卷煮至完全熟透。','最后放毛肚烫至熟透即可；避免久煮，口感会变韧。底料品牌不同，热量和咸度会有差异。'],
      'chaoshan-beef-hotpot':['白萝卜切片、玉米切段，牛肉片提前解冻；准备姜 6 克和盐 2 克。','锅中加约 900 毫升清水和姜片，放入萝卜、玉米煮至熟软。','转中火，将牛上脑分批放入汤中煮至完全熟透。','加盐调味并撒香菜；沙茶酱或普宁豆酱可另作蘸料，未计入本次热量。'],
      'lamb-radish-soup':['白萝卜切片，姜切片，香菜切段；羊肉卷分开备用。','锅中加约 800 毫升水、姜 8 克和料酒 8 克，放白萝卜煮 10–12 分钟。','转中火放入羊肉卷，撇去浮沫，煮至肉片完全变色熟透。','加盐 2 克和白胡椒 0.5 克，关火后撒香菜。'],
      'mushroom-chicken':['鸡腿肉切块，香菇切片，胡萝卜切薄片；玉米淀粉 4 克加少量水调开。','鸡肉加生抽 10 克、料酒 8 克和淀粉水抓匀，腌 10 分钟。','锅中加食用油 8 克，中火把鸡肉煎至表面金黄，再加入香菇和胡萝卜翻炒 2 分钟。','加约 100 毫升水和蚝油 5 克，盖锅焖 8–10 分钟至鸡肉熟透、汤汁收浓。'],
      'pork-cabbage-tofu':['猪肉片切成适口大小，白菜切块，豆腐切厚片，姜切丝。','锅中加食用油 8 克和姜 5 克炒香，放入猪肉片炒至完全变色。','加入白菜和生抽 10 克翻炒，加约 300 毫升水；放入豆腐后小火炖 12–15 分钟。','白菜变软后加盐 3 克调味，轻轻翻动避免豆腐碎裂。'],
      'pepper-beef':['牛肉片加入生抽 10 克、玉米淀粉 4 克和黑胡椒 0.5 克抓匀，腌 10 分钟；彩椒、洋葱切条。','锅烧热加入食用油 8 克，大火快速滑炒牛肉约 1 分钟，刚变色即盛出。','用锅中余油炒洋葱和彩椒 2–3 分钟，保持蔬菜爽脆。','倒回牛肉，加蚝油 5 克，大火翻匀约 30 秒后关火。'],
      'garlic-broccoli-mushroom':['西兰花掰小朵焯水 1 分钟后沥干，蘑菇切片，蒜头切末。','锅中加入食用油 5 克，中火炒香蒜末约 20 秒，避免焦糊。','加入蘑菇翻炒 3 分钟至变软，再加入西兰花大火翻炒 2 分钟。','加盐 2 克调味，可加 1–2 汤匙焯菜水帮助挂味，炒匀出锅。'],
      'pork-rib-potato-soup':['排骨冷水下锅煮沸 2 分钟，捞出洗净浮沫；土豆和胡萝卜切块。','排骨、姜 8 克、料酒 10 克和约 1.2 升清水入锅，煮开后撇沫。','转小火加盖炖 45 分钟，加入土豆和胡萝卜再炖 20 分钟。','确认排骨和蔬菜熟软后加盐 3 克；可撇去表面浮油再喝汤。'],
      'eggplant-pork':['猪肉片加生抽 8 克抓匀，茄子切条、青椒切片。','锅中加入食用油 10 克，先把茄子中火煸至变软并盛出。','用锅中余油炒猪肉片至完全变色，加入青椒翻炒 1 分钟。','倒回茄子，加蚝油 5 克和白糖 2 克翻炒 1–2 分钟；若偏干可加少量水。'],
      'mushroom-egg':['鸡蛋打散，香菇和平菇切片；准备食用油 6 克、生抽 5 克和盐 2 克。','锅中加一半食用油，蛋液炒至八成熟后盛出。','加入剩余食用油炒香菌菇 3–4 分钟，炒至出水后收干一些。','倒回鸡蛋，加生抽和盐翻匀约 1 分钟，确保鸡蛋完全熟透。'],
      'fruit-bowl':['苹果、香蕉和葡萄洗净；苹果去核切块，香蕉切片，葡萄去梗。','柠檬汁 5 克与蜂蜜 5 克加 1 茶匙温水调匀，做成轻薄果汁酱。','水果装盘后淋上果汁酱，拌匀即可；想控制糖分可省略蜂蜜。','水果品种可按库存替换；替换后热量会按当前菜谱用料估算。'],
      'fish-fragrant-pork':['里脊切细丝，加入玉米淀粉 5 克和生抽 3 克抓匀；木耳泡发，竹笋、青椒切丝。','用米醋 8 克、白糖 6 克、生抽 5 克和少量清水调成碗汁。','锅中加食用油 8 克，先滑炒肉丝至变色盛出；锅中炒香豆瓣酱 8 克。','加入木耳、竹笋和青椒炒熟，倒回肉丝，淋入碗汁大火翻匀收汁。'],
      'mapo-tofu':['豆腐切约 2 厘米块，蒜切末；猪绞肉准备好。','锅中加食用油 8 克炒熟肉末，加入豆瓣酱 12 克和蒜末炒香。','加约 180 毫升水、生抽 8 克和辣椒油 3 克，放入豆腐小火煮 5 分钟。','轻轻翻动避免豆腐碎裂，汤汁收至合适浓度后关火。'],
      'twice-cooked-pork':['五花肉整块冷水下锅，煮约 20 分钟至熟透，放凉后切薄片。','青椒切片、蒜切片；锅中不放油，放肉片煸出部分油脂。','加入豆瓣酱 10 克炒出红油，放蒜片和青椒翻炒。','加生抽 5 克调味，青椒断生即可出锅。'],
      'mushu-pork':['木耳泡发，黄瓜切片，里脊切片并用少许淀粉抓匀，鸡蛋打散。','锅中加食用油 8 克炒鸡蛋至凝固，盛出备用。','滑炒里脊至变色，加入木耳和黄瓜炒熟。','倒回鸡蛋，加生抽 8 克和盐 2 克翻匀即可。'],
      'sweet-sour-pork':['里脊切条，加入蛋液和玉米淀粉 10 克抓匀；用生抽 5 克简单调味。','锅中放食用油 12 克，中火分批煎炸肉条至金黄熟透，捞出沥油。','另锅加米醋 12 克、白糖 12 克和少量水，小火煮至糖溶化。','汁液微稠时放入肉条和青椒，快速翻匀裹汁后出锅。'],
      'scallion-tofu':['豆腐切厚片，大葱切段；锅中加食用油 8 克。','豆腐两面煎至金黄，取出备用；用锅中余油把大葱煸香。','加生抽 10 克、蚝油 5 克和约 100 毫升水煮开。','放回豆腐，小火烧 5 分钟，中途翻面一次，汤汁略收后装盘。'],
      'cantonese-choy-sum':['菜心洗净，蒜头切末；锅中烧足量水至沸腾。','加入菜心焯 1–2 分钟，梗部熟而仍爽脆时捞出沥水。','菜心淋生抽 10 克，顶部放蒜末。','另锅将食用油 5 克烧热后淋在蒜末上，趁热上桌。'],
      'cantonese-soy-chicken':['鸡腿擦干，香菇泡发，香葱打结，姜切片。','锅中加食用油 3 克，将鸡腿表面煎至微黄。','加生抽 20 克、老抽 8 克、料酒 8 克、白糖 5 克、姜 8 克、葱 10 克和约 250 毫升水。','小火加盖焖 25–30 分钟，中途翻面并加入香菇；确认熟透后开盖收汁切块。'],
      'cantonese-steamed-ribs':['排骨冲洗沥干，蒜头切末；加入生抽 8 克、料酒 5 克和玉米淀粉 5 克抓匀腌 15 分钟。','蒸锅加水烧开，把排骨平铺在浅盘中，避免堆叠过厚。','水开后大火蒸 25–30 分钟，视排骨块大小延长时间。','确认排骨熟透后撒葱花即可食用。'],
      'garlic-water-spinach':['空心菜洗净切段，蒜头拍碎切末。','锅烧热后加入食用油 5 克，放蒜末炒香但不要炒焦。','先放菜梗翻炒约 30 秒，再放菜叶大火翻炒。','菜叶变软后加盐 2 克，快速翻匀出锅。'],
      'shiitake-bokchoy':['香菇切片，小白菜洗净切段，蒜头切末。','锅中加食用油 5 克炒香蒜末和香菇，炒至香菇变软。','先放小白菜梗翻炒，再加入菜叶炒至断生。','加蚝油 5 克和盐 1 克调味，翻匀后立即出锅。'],
      'celery-beef':['牛肉片加入生抽 8 克和玉米淀粉 5 克抓匀腌 10 分钟；芹菜切段，红椒切丝。','锅烧热加食用油 8 克，快速滑炒牛肉至七成熟后盛出。','用锅中余油炒芹菜和红椒 2–3 分钟，保留爽脆口感。','倒回牛肉大火翻炒至熟透，尝味后出锅。'],
      'garlic-chicken-wings':['鸡翅擦干，两面划两刀；蒜头切末。','锅中加食用油 5 克，将鸡翅两面煎至金黄。','加入蒜末、生抽 10 克、蜂蜜 8 克、黑胡椒 1 克和少量水。','加盖小火焖 12–15 分钟，中途翻面；确认鸡翅熟透后开盖收汁。']
    };
    const regionalNames={sichuan:'川菜',shandong:'鲁菜',cantonese:'粤菜',northeast:'东北菜',shanghai:'上海菜',korean:'韩国料理',japanese:'日本菜',western:'西餐',french:'法餐',turkish:'土耳其菜'};
    const regionalStyleNames={meatstir:'炒菜·肉菜',vegstir:'炒菜·素菜',braise:'炖烧',soup:'汤菜',steam:'蒸菜',rice:'主食',cold:'凉菜',grill:'煎烤',deepfry:'炸物',bake:'烤箱菜',pasta:'意面',griddle:'煎制'};
    const regionalSeasonings={meatstir:[['食用油',8],['生抽',8],['玉米淀粉',4],['盐',1]],vegstir:[['食用油',6],['生抽',5],['盐',2]],braise:[['食用油',6],['生抽',10],['老抽',4],['白糖',4],['姜',5]],soup:[['姜',6],['料酒',6],['盐',2]],steam:[['生抽',8],['姜',5],['葱',5]],rice:[['食用油',6],['生抽',6],['盐',1]],cold:[['生抽',8],['米醋',8],['香油',5],['白糖',3]],grill:[['食用油',5],['盐',2],['黑胡椒',1],['柠檬汁',5]],deepfry:[['食用油',12],['盐',2],['黑胡椒',1]],bake:[['食用油',5],['盐',2],['黑胡椒',1]],pasta:[['橄榄油',6],['盐',2],['黑胡椒',1]],griddle:[['食用油',6],['盐',2],['生抽',5]]};
    const regionalFlavorSeasonings={japanese:[['生抽',5],['料酒',5]],western:[['橄榄油',5],['黑胡椒',1]],french:[['黄油',5],['百里香',1]],turkish:[['橄榄油',5],['孜然粉',2],['红椒粉',2]]};
    const regionalSpecialSeasonings={'jp-teriyaki-chicken':[['照烧汁',15]],'jp-curry-chicken':[['日式咖喱块',20]],'jp-miso-salmon-soup':[['味噌',12]],'fr-bourguignon':[['红酒',35]],'fr-mustard-chicken':[['芥末酱',8]],'fr-orange-duck':[['橙汁',10]]};
    const regionalMethod=(item,seasonings)=>{const names=item[7].map(([name])=>name),seasoningText=seasonings.map(([name,grams])=>`${name} ${grams} 克`).join('、'),prep=`将${names.join('、')}洗净并按菜式切配；肉类切片或切块，叶菜沥干。`;if(item[5]==='meatstir')return [prep,'肉类用少量生抽和玉米淀粉抓匀腌 10 分钟；热锅加油，先把肉炒至变色盛出。','用锅中余油炒香蔬菜，按耐熟程度依次下锅。',`倒回主料，加入${seasoningText}调味；肉类彻底熟透后翻匀出锅。`];if(item[5]==='vegstir')return [prep,'锅中加少量清水，先将耐炒食材焯至半熟后沥干。','热锅加油，炒香配菜并保持大火翻炒。',`加入${seasoningText}调味，食材熟透后出锅。`];if(item[5]==='braise')return [prep,'锅中加少量油，将主料表面煎香；再加入配菜翻炒片刻。',`加入${seasoningText}和约 400 毫升热水煮开，转小火加盖慢炖。`,'按食材耐煮程度调整时间，确认肉类熟透、汤汁浓度合适后出锅。'];if(item[5]==='soup')return [prep,'肉类先焯水去浮沫；蔬菜切成适口大小。',`主料加约 800 毫升清水和${seasoningText}煮沸，转小火炖至主料熟软。`,'加入易熟配料再煮数分钟，确认肉类熟透后调味盛出。'];if(item[5]==='steam')return [prep,`主料放入蒸盘，加入${seasoningText}拌匀或淋在表面，腌 10 分钟。`,'蒸锅水烧开后放入蒸盘，盖盖以中大火蒸 12–25 分钟，时间按厚度调整。','确认肉类或鱼肉中心熟透，出锅后拌匀盘中汤汁。'];if(item[5]==='rice')return [prep,'大米或米饭按菜式准备；蔬菜切丁，肉类切小块并先炒熟。','热锅加入少量油，炒香配菜；加入米饭或主食及适量水。',`加入${seasoningText}调味，按主食类型焖煮或翻炒至熟透。`];if(item[5]==='cold')return [prep,'需要熟制的食材分别煮熟或焯水，捞出沥干并放凉。',`将${seasoningText}调匀成凉拌汁，按口味调整咸酸度。`,'淋在食材上拌匀，冷藏片刻后食用。'];if(item[5]==='grill')return [prep,`主料用${seasoningText}腌 10–15 分钟；平底锅或烤盘预热。`,'刷薄油后以中火煎烤，翻面至两面上色；蔬菜可同时煎熟。','肉类中心确认熟透后出锅，静置 2 分钟再切。'];if(item[5]==='deepfry')return [prep,`按菜式将主料裹粉、蛋液或面包糠；油温加热至约 170°C。`,'分批下锅炸至金黄熟透，避免一次放入过多导致油温下降。',`捞出沥油，撒上${seasoningText}调味后趁热食用。`];if(item[5]==='bake')return [prep,'烤箱预热至 190°C；将主料按菜式铺入烤盘，表面刷少量油。',`撒上${seasoningText}，烘烤至表面上色；时间按食材厚度调整。`,'确认肉类中心熟透或蔬菜软熟后取出，稍微放凉再上桌。'];if(item[5]==='pasta')return [prep,'意面或通心粉放入沸水，加少许盐煮至有嚼劲，留少量煮面水。','另起锅加入油和配料，炒熟肉类或蔬菜后加入奶油、番茄或奶酪酱。',`放入沥好的面和${seasoningText}，加少量煮面水翻匀；肉类确认熟透后出锅。`];if(item[5]==='griddle')return [prep,'按菜式将主料切碎或调成面糊；平底锅预热后刷薄油。','倒入面糊或铺上主料，中小火煎至底面定型并上色后翻面。',`加入${seasoningText}调味，继续煎至中心熟透即可。`];return [prep,'将食材切成适口大小并预热锅具。',`加入${seasoningText}，按菜式分批烹调并适时翻面。`,'确认所有食材熟透、调味均匀后盛出。']};
    const regionalLightRecipeIds=new Set(['steamed-sea-bass','spinach-tofu-soup','shandong-salad','vinegar-cabbage','wood-ear-egg','northeast-cold-salad','jp-miso-salmon-soup','jp-salmon-grill','jp-chawanmushi','jp-hiyayakko','west-roasted-vegetables','west-pumpkin-soup','fr-ratatouille','fr-nicoise','fr-salmon-papillote','fr-lentil-salad','tr-menemen','tr-lentil-soup','tr-cacik','tr-eggplant-yogurt','tr-baked-seabass']);
    extraRegionalRecipes.forEach(item=>{const [region,id,name,emoji,time,style,description,ingredients]=item,seasonings=[...regionalSeasonings[style],...(region==='sichuan'?[['豆瓣酱',8],['辣椒油',3]]:region==='korean'?[['韩式辣酱',12],['香油',3]]:[]),...(regionalFlavorSeasonings[region]||[]),...(regionalSpecialSeasonings[id]||[])],tags=['regional',region],label=[regionalNames[region],regionalStyleNames[style]];if(style==='meatstir'){tags.push('stirfry','meat');label.push('肉菜')}if(style==='vegstir'){tags.push('stirfry','vegetarian');label.push('素菜');tags.push('light');label.push('减脂餐')}if(style==='soup'){tags.push('soup')}if(regionalLightRecipeIds.has(id)&&!tags.includes('light')){tags.push('light');label.push('减脂餐')}const steps=regionalMethod(item,seasonings);recipes.push({id,name,emoji,time,kcal:0,tags,label,description,ingredients,steps});recipeSeasonings[id]=seasonings;recipeMethods[id]=steps});
    const uniqueRecipesByName=new Map();recipes.forEach(recipe=>{const key=recipe.name.normalize('NFKC').toLocaleLowerCase().replace(/[\s·\-—]/g,'');const existing=uniqueRecipesByName.get(key);if(!existing){uniqueRecipesByName.set(key,recipe);return}recipe.tags.forEach(tag=>{if(!existing.tags.includes(tag))existing.tags.push(tag)});recipe.label.forEach(label=>{if(!existing.label.includes(label))existing.label.push(label)});delete recipeSeasonings[recipe.id];delete recipeMethods[recipe.id]});recipes.splice(0,recipes.length,...uniqueRecipesByName.values());
    const starter = [];
    function expiryDateKey(item){const d=new Date(item.added);d.setHours(0,0,0,0);d.setDate(d.getDate()+Number(item.expiry));return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
    function supportsMilliliters(name){return foods.find(item=>item.name===name)?.category==='饮料'}
